def calculate_a(n, memo):
    if n in memo:
        return memo[n]
    if n == 1 or n == 2:
        return 1

    # Recursive calculation
    try:
        # Needs a_n-1 first
        a_prev = calculate_a(n - 1, memo)

        # Calculate a_{a_{n-1}}
        a_term1 = calculate_a(a_prev, memo)

        # Calculate a_{n - a_{n-1}}
        a_term2 = calculate_a(n - a_prev, memo)

        result = a_term1 + a_term2
        memo[n] = result
        return result
    except RecursionError:
        # Handle potential depth issues for testing
        return None

# Test for small powers of 2
powers_of_2 = [2, 4, 8, 16, 32, 64]
results = {}
memo = {}
for p in powers_of_2:
    val = calculate_a(p, memo)
    results[p] = val

print(results)

def calculate_sequence(N):
    a = {}
    if N >= 1:
        a[1] = 1
    if N >= 2:
        a[2] = 1

    for n in range(3, N + 1):
        # a_n = a_{a_{n-1}} + a_{n - a_{n-1}}

        # We rely on a_{n-1} being known
        an_minus_1 = a[n-1]

        # Check if required indices are defined (they should be if the sequence is positive)
        # a_a_{n-1}
        idx1 = an_minus_1
        if idx1 not in a:
            raise ValueError(f"Index {idx1} required for a_{n} is not yet defined.")

        # a_{n - a_{n-1}}
        idx2 = n - an_minus_1
        if idx2 <= 0 or idx2 not in a:
            raise ValueError(f"Index {idx2} required for a_{n} is not yet defined or non-positive.")

        a[n] = a[idx1] + a[idx2]

    return a

